#!/usr/bin/env python3
"""omics/bulk_de_pipeline — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "omics"
SKILL = "bulk_de_pipeline"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'bulk_de_pipeline', 'matrix_path': '', 'n_cells_post_qc': 0, 'cluster_sizes': {}, 'marker_genes_per_cluster': {}, 'umap_png': '', 'diagnostics': {'brain': 'omics', 'archetype': 'omics_scrna'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Bulk RNA-seq DE 简化版:scanpy + rank_genes_groups(Wilcoxon,而非 R DESeq2)。
    host_env=praxis-omics(无 pydeseq2/DESeq2 R,降级 Wilcoxon)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    counts_csv = payload.get("counts_csv")
    meta_csv = payload.get("metadata_csv")
    group_col = payload.get("group_col", "condition")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "scanpy.rank_genes_groups (wilcoxon)", "fallback_from": "DESeq2"}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "matrix_path": "", "n_cells_post_qc": 0,
                "cluster_sizes": {}, "marker_genes_per_cluster": {}, "umap_png": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not counts_csv or not _os.path.isfile(counts_csv):
        return {"ok": False, "error": "需要 counts_csv (rows=genes, cols=samples)",
                "diagnostics": diagnostics}
    if not meta_csv or not _os.path.isfile(meta_csv):
        return {"ok": False, "error": "需要 metadata_csv", "diagnostics": diagnostics}
    out_csv = _tempfile.NamedTemporaryFile(suffix="_de.csv", delete=False).name
    script = (
        "import json, sys, pandas as pd, scanpy as sc, anndata as ad_mod\n"
        f"counts = pd.read_csv({counts_csv!r}, index_col=0)\n"
        f"meta = pd.read_csv({meta_csv!r}, index_col=0)\n"
        "ad = ad_mod.AnnData(X=counts.T.values, obs=meta.loc[counts.columns], var=pd.DataFrame(index=counts.index))\n"
        "sc.pp.normalize_total(ad); sc.pp.log1p(ad)\n"
        f"sc.tl.rank_genes_groups(ad, {group_col!r}, method='wilcoxon')\n"
        "rgg = ad.uns['rank_genes_groups']\n"
        "groups = rgg['names'].dtype.names\n"
        "rows = []\n"
        "for g in groups:\n"
        "    for i in range(len(rgg['names'])):\n"
        "        rows.append({'group': g, 'gene': rgg['names'][g][i],\n"
        "                     'logfc': float(rgg['logfoldchanges'][g][i]),\n"
        "                     'pval': float(rgg['pvals'][g][i]),\n"
        "                     'padj': float(rgg['pvals_adj'][g][i])})\n"
        "df = pd.DataFrame(rows)\n"
        f"df.to_csv({out_csv!r}, index=False)\n"
        f"json.dump({{'matrix_path': {out_csv!r}, 'n_cells_post_qc': int(ad.n_obs),\n"
        "           'cluster_sizes': {str(g): int((df.group==g).sum()) for g in groups},\n"
        "           'marker_genes_per_cluster': {g: list(df[df.group==g].head(10).gene) for g in groups}}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "bulk DE 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "umap_png": "",
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
